{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import fs from 'node:fs'
import { parseDocument } from './parser.js'
import { renderJson, renderKeys } from './render.js'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'json' && mode[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

let root
try {
  const text = fs.readFileSync(0, 'utf8')
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  root = parseDocument(lines)
} catch (e) {
  if (e && e.isConfigError) {
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(mode[0] === 'json' ? renderJson(root) : renderKeys(root))
"}

{"file_path":"src/render.js","content":"function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (m) => [...m.keys()].sort(cmp)

function js(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  switch (node.t) {
    case 'table': {
      const ks = sortedKeys(node.m)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${js(node.m.get(k), indent + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!node.items.length) return '[]'
      return '[\n' + node.items.map((n) => pad + js(n, indent + 1)).join(',\n') + '\n' + end + ']'
    default:
      return JSON.stringify(node.v)
  }
}

export function renderJson(root) {
  return js(root, 0) + '\n'
}

export function renderKeys(root) {
  const out = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node.m)) {
        const p = path === null ? k : `${path}.${k}`
        const c = node.m.get(k)
        out.push(`${p} ${c.t}`)
        walk(c, p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return out.length ? out.join('\n') + '\n' : ''
}
"}

{"file_path":"src/parser.js","content":"function fail(msg) {
  const e = new Error(msg)
  e.isConfigError = true
  throw e
}

const newTable = () => ({ t: 'table', m: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

/** Descend through `names`, creating tables; returns the table reached. */
function walk(tbl, names, base) {
  let cur = tbl
  for (let i = 0; i < names.length; i++) {
    const n = names[i]
    let next = cur.m.get(n)
    if (!next) {
      next = newTable()
      cur.m.set(n, next)
    } else if (next.t === 'array' && next.aot) {
      next = next.items[next.items.length - 1]
    } else if (next.t !== 'table') {
      fail(`${[...base, ...names.slice(0, i + 1)].join('.')} is not a table`)
    }
    cur = next
  }
  return cur
}

function assign(tbl, names, value, base) {
  const parent = walk(tbl, names.slice(0, -1), base)
  const last = names[names.length - 1]
  if (parent.m.has(last)) fail(`key ${[...base, ...names].join('.')} is defined twice`)
  parent.m.set(last, value)
}

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (this.i < this.s.length && isWs(this.s[this.i])) this.i++
  }
  /** True at end of line or at a comment start. */
  atEnd() {
    return this.i >= this.s.length || this.c === '#' || this.c === ';'
  }
  name() {
    const c = this.c
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }
  basic() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c !== '\\') {
        out += c
        this.i++
        continue
      }
      this.i++
      if (this.i >= this.s.length) fail('unterminated string')
      const e = this.s[this.i]
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) {
        out += map[e]
        this.i++
      } else if (e === 'u') {
        const h = this.s.slice(this.i + 1, this.i + 5)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 5
      } else {
        const cp = String.fromCodePoint(this.s.codePointAt(this.i))
        fail(`invalid escape \\${cp}`)
      }
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return v
  }
  value(base) {
    const c = this.c
    if (this.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail(`invalid value ${w}`)
  }
  array(base) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']' && true) {
        this.i++
        return { t: 'array', items, aot: false }
      }
      items.push(this.value(base))
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ',') {
        this.i++
        continue
      }
      if (this.c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      fail('trailing text after a value')
    }
  }
  inline(base) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.c === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value([...base, ...names])
      assign(tbl, names, v, base)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c === ',') {
        this.i++
        continue
      }
      if (this.c === '}') {
        this.i++
        return tbl
      }
      fail('trailing text after a value')
    }
  }
}

export function parseDocument(lines) {
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((text, idx) => {
    try {
      const L = new Line(text)
      L.ws()
      if (L.i >= text.length || L.c === '#' || L.c === ';') return
      if (text[0] === '[') {
        const aot = text[1] === '['
        L.i = aot ? 2 : 1
        L.ws()
        const names = L.dotted()
        L.ws()
        for (let k = 0; k < (aot ? 2 : 1); k++) {
          if (L.c !== ']') fail('unterminated table header')
          L.i++
        }
        L.ws()
        if (!L.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, names.slice(0, -1), [])
        const last = names[names.length - 1]
        const path = names.join('.')
        const ex = parent.m.get(last)
        if (aot) {
          if (!ex) {
            const t = newTable()
            parent.m.set(last, { t: 'array', items: [t], aot: true })
            cur = t
          } else if (ex.t === 'array' && ex.aot) {
            const t = newTable()
            ex.items.push(t)
            cur = t
          } else fail(`${path} is not an array of tables`)
        } else if (!ex) {
          const t = newTable()
          t.header = true
          parent.m.set(last, t)
          cur = t
        } else if (ex.t !== 'table') {
          fail(`${path} is not a table`)
        } else if (ex.header) {
          fail(`table ${path} is defined twice`)
        } else {
          ex.header = true
          cur = ex
        }
        curPath = names
        return
      }
      const names = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      L.ws()
      const v = L.value([...curPath, ...names])
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, names, v, curPath)
    } catch (e) {
      if (e.isConfigError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}
"}

