{"command":"cat > src/cli.js <<'EOF'
#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) {
    super(msg)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const costs = new Map()
  const deps = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (costs.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      costs.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      depLines.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const names of depLines) {
    for (const nm of names) if (!costs.has(nm)) throw new Fail(`error: unknown task ${nm}`)
  }
  for (const nm of costs.keys()) deps.set(nm, new Set())
  for (const [name, ...ds] of depLines) for (const d of ds) deps.get(name).add(d)
  const sorted = new Map()
  for (const nm of [...costs.keys()].sort(cmp)) sorted.set(nm, [...deps.get(nm)].sort(cmp))
  return { costs, deps: sorted, names: [...sorted.keys()] }
}

function checkCycle({ deps, names }) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of deps.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v))
        cyc.push(v)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const nm of names) if (!state.get(nm)) visit(nm)
}

function analyze(g) {
  const info = new Map()
  const go = (u) => {
    let r = info.get(u)
    if (r) return r
    let start = 0n
    let depth = 0
    for (const d of g.deps.get(u)) {
      const x = go(d)
      if (x.finish > start) start = x.finish
      if (x.depth + 1 > depth) depth = x.depth + 1
    }
    r = { start, finish: start + g.costs.get(u), depth }
    info.set(u, r)
    return r
  }
  let total = 0n
  for (const nm of g.names) {
    const r = go(nm)
    if (r.finish > total) total = r.finish
  }
  return { info, total }
}

function pack(g, workers) {
  const rev = new Map(g.names.map((n) => [n, []]))
  for (const [n, ds] of g.deps) for (const d of ds) rev.get(d).push(n)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let best = 0n
    for (const v of rev.get(u)) {
      const p = pr(v)
      if (p > best) best = p
    }
    best += g.costs.get(u)
    prio.set(u, best)
    return best
  }
  g.names.forEach(pr)
  const finish = new Map()
  const started = new Set()
  const busy = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n
  let makespan = 0n
  while (started.size < g.names.length) {
    for (;;) {
      let w = busy.findIndex((b) => b <= t)
      if (w < 0) break
      let pick = null
      for (const n of g.names) {
        if (started.has(n)) continue
        if (!g.deps.get(n).every((d) => finish.has(d) && finish.get(d) <= t)) continue
        if (pick === null || prio.get(n) > prio.get(pick)) pick = n
      }
      if (pick === null) break
      const f = t + g.costs.get(pick)
      started.add(pick)
      finish.set(pick, f)
      runs[w].push(`${pick}@${t}-${f}`)
      busy[w] = f
      if (f > makespan) makespan = f
    }
    if (started.size >= g.names.length) break
    let next = null
    for (const b of busy) if (b > t && (next === null || b < next)) next = b
    if (next === null) break
    t = next
  }
  const out = runs.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}`)
  out.push(`makespan ${makespan}`)
  return out
}

function main() {
  const a = process.argv.slice(2)
  const usage = new Fail('error: usage: cli.js waves|explain|pack <workers>')
  let workers = 0
  if (a[0] === 'waves' || a[0] === 'explain') {
    if (a.length !== 1) throw usage
  } else if (a[0] === 'pack') {
    if (a.length !== 2) throw usage
    if (!/^[1-9][0-9]*$/.test(a[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(a[1])
  } else throw usage

  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }
  const g = parse(text)
  checkCycle(g)
  const out = []
  if (a[0] === 'pack') {
    out.push(...pack(g, workers))
  } else {
    const { info, total } = analyze(g)
    if (a[0] === 'waves') {
      const waves = []
      for (const nm of g.names) (waves[info.get(nm).depth] ||= []).push(nm)
      waves.forEach((ws, k) => out.push(`wave ${k}: ${ws.join(' ')}`))
    } else {
      for (const nm of g.names) {
        const r = info.get(nm)
        out.push(`${nm} start=${r.start} finish=${r.finish} depth=${r.depth}`)
      }
    }
    out.push(`total ${total}`)
  }
  process.stdout.write(out.join('\n') + '\n')
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
