const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let cands = null
let seenBallot = false
const ballots = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'candidates') {
    if (cands !== null || seenBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = w.slice(1)
  } else if (w[0] === 'ballot') {
    seenBallot = true
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const known = new Set(cands || [])
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (!known.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
})
if (cands === null) fail('error: no candidates')

const continuing = new Set(cands)
const history = []
const out = []
let winner = null
let roundNo = 0
for (;;) {
  roundNo++
  const votes = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      votes.set(c, votes.get(c) + b.count)
      active += b.count
    }
  }
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  history.push(votes)
  const order = [...votes.keys()].sort((a, b) => (votes.get(a) > votes.get(b) ? -1 : votes.get(a) < votes.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  let line = `round ${roundNo}: ` + order.map((c) => `${c}=${votes.get(c)}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const top = order.find((c) => votes.get(c) * 2n > active)
  if (top !== undefined) { winner = top; break }
  let tied = [...continuing]
  const min = tied.reduce((m, c) => (votes.get(c) < m ? votes.get(c) : m), votes.get(tied[0]))
  tied = tied.filter((c) => votes.get(c) === min)
  for (;;) {
    if (tied.length === 1) break
    let split = false
    for (const h of history) {
      const vs = tied.map((c) => h.get(c))
      if (vs.some((v) => v !== vs[0])) {
        const m = vs.reduce((a, b) => (b < a ? b : a))
        tied = tied.filter((c) => h.get(c) === m)
        split = true
        break
      }
    }
    if (!split) break
  }
  const elim = tied.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
out.push(winner === null ? 'no winner' : `winner ${winner}`)
process.stdout.write(mode === 'tally' ? `rounds ${roundNo}\n${out[out.length - 1]}\n` : out.join('\n') + '\n')
EOF
