import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const newTable = () => ({ t: 'table', m: new Map(), defined: false })
const join = (p, n) => (p === '' ? n : p + '.' + n)

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  // at end of line or a comment start
  eol() { return this.c === undefined || this.c === '#' || this.c === ';' }
}

function parseString(L) {
  const q = L.c
  L.i++
  let out = ''
  for (;;) {
    const c = L.c
    if (c === undefined) fail('unterminated string')
    L.i++
    if (c === q) return out
    if (q === "'" || c !== '\\') { out += c; continue }
    const e = L.c
    if (e === undefined) fail('unterminated string')
    L.i++
    if (e === '"') out += '"'
    else if (e === '\\') out += '\\'
    else if (e === 'n') out += '\n'
    else if (e === 't') out += '\t'
    else if (e === 'r') out += '\r'
    else if (e === '0') out += '\0'
    else if (e === 'u') {
      const h = L.s.slice(L.i, L.i + 4)
      if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(h, 16))
      L.i += 4
    } else fail('invalid escape \\' + e)
  }
}

function parseName(L) {
  const c = L.c
  if (c === '"' || c === "'") return parseString(L)
  if (!isBare(c)) fail('expected a name')
  const st = L.i
  while (isBare(L.c)) L.i++
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  const names = [parseName(L)]
  for (;;) {
    const save = L.i
    L.ws()
    if (L.c !== '.') { L.i = save; return names }
    L.i++
    L.ws()
    names.push(parseName(L))
  }
}

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function parseValue(L, path) {
  const c = L.c
  if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') fail('expected a value')
  if (c === '"' || c === "'") return { t: 'string', v: parseString(L) }
  if (c === '[') {
    L.i++
    const items = []
    L.ws()
    if (L.c === ']') { L.i++; return { t: 'array', items, aot: false } }
    for (;;) {
      L.ws()
      items.push(parseValue(L, path + '[' + items.length + ']'))
      L.ws()
      if (L.c === ',') {
        L.i++
        L.ws()
        if (L.c === ']') { L.i++; break }
      } else if (L.c === ']') { L.i++; break } else fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }
  if (c === '{') {
    L.i++
    const tab = newTable()
    L.ws()
    if (L.c === '}') { L.i++; return tab }
    if (L.eol()) fail('unterminated inline table')
    for (;;) {
      L.ws()
      const names = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected = in an inline table')
      L.i++
      L.ws()
      const full = names.reduce(join, path)
      const v = parseValue(L, full)
      assign(tab, path, names, v)
      L.ws()
      if (L.c === ',') { L.i++; continue }
      if (L.c === '}') { L.i++; return tab }
      fail('unterminated inline table')
    }
  }
  const st = L.i
  while (L.c !== undefined && !isWs(L.c) && !',]};'.includes(L.c)) L.i++
