// Walk (creating) the tables for names[0..n-1] below `cur`.
function walk(cur, prefix, names, n, make) {
  let p = prefix
  for (let i = 0; i < n; i++) {
    p = join(p, names[i])
    let e = cur.m.get(names[i])
    if (e === undefined) { e = newTable(); cur.m.set(names[i], e) }
    if (e.t === 'array' && e.aot) e = e.items[e.items.length - 1]
    if (e.t !== 'table') fail(p + ' is not a table')
