        if (!L.eol()) fail('trailing text after a table header')
        const last = names.length - 1
        const parent = walk(root, '', names, last)
        const full = names.join('.')
        const k = names[last]
        let e = parent.m.get(k)
        if (aot) {
          if (e === undefined) { e = { t: 'array', items: [], aot: true }; parent.m.set(k, e) }
          if (e.t !== 'array' || !e.aot) fail(full + ' is not an array of tables')
          const nt = newTable()
          e.items.push(nt)
          cur = nt
        } else {
          if (e === undefined) { e = newTable(); parent.m.set(k, e) }
          if (e.t !== 'table') fail(full + ' is not a table')
          if (e.defined) fail('table ' + full + ' is defined twice')
          e.defined = true
          cur = e
        }
