import { readFileSync } from 'node:fs'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'replay' && mode[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function num(field, s, least) {
  if (!UINT.test(s) || BigInt(s) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (lastTick !== null) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = num('capacity', f[2], 1)
        const refill = num('refill', f[3], 0)
        const per = num('per', f[4], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per })
      } else if (d === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const limit = num('limit', f[2], 0)
        const span = num('span', f[3], 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'window', limit, span })
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        for (const p of f.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
        routes.set(f[1], f.slice(2).map((p) => policies.get(p)))
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num('tick', f[1], 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: f[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function newState(p, tick) {
  if (p.kind === 'bucket') return { scaled: p.capacity * p.per, last: tick }
  return { ticks: [] }
}
function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const max = p.capacity * p.per
    s.scaled += p.refill * (tick - s.last)
    if (s.scaled > max) s.scaled = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
}
const allows = (p, s) => (p.kind === 'bucket' ? s.scaled >= p.per : BigInt(s.ticks.length) < p.limit)
function record(p, s, tick) {
  if (p.kind === 'bucket') s.scaled -= p.per
  else s.ticks.push(tick)
}

function run(text) {
  const { routes, events } = parse(text)
  const states = new Map()
  const out = []
  const counts = new Map()
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const prefix of routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let denier = null
    if (best !== null) {
      const ps = routes.get(best)
      const ss = ps.map((p) => {
        const id = p.name + '\0' + key
        if (!states.has(id)) states.set(id, newState(p, tick))
        const s = states.get(id)
        advance(p, s, tick)
        return s
      })
      for (let j = 0; j < ps.length; j++) {
        if (!allows(ps[j], ss[j])) { denier = ps[j].name; break }
      }
      if (denier === null) ps.forEach((p, j) => record(p, ss[j], tick))
    }
    const c = counts.get(key) ?? { a: 0, d: 0 }
    if (denier === null) { c.a++; ta++ } else { c.d++; td++ }
    counts.set(key, c)
    out.push(denier === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denier}`)
  }
  if (mode[0] === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  return keys.map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`).join('') +
    `total allowed=${ta} denied=${td}\n`
}

let result
try {
  result = run(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(result)
