export function parse(s) {
  let scheme, authority, query, fragment
  const m = /^[^:/?#]+:/.exec(s)
  if (m) { scheme = m[0].slice(0, -1); s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    if (e < 0) { authority = s.slice(2); s = '' } else { authority = s.slice(2, 2 + e); s = s.slice(2 + e) }
  }
  const h = s.indexOf('#')
  if (h >= 0) { fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { query = s.slice(q + 1); s = s.slice(0, q) }
  return { scheme, authority, path: s, query, fragment }
}

export function splitAuthority(a) {
  let userinfo, port
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const c = a.indexOf(':', a.lastIndexOf(']') + 1)
  if (c >= 0) { port = a.slice(c + 1); a = a.slice(0, c) }
  return { userinfo, host: a, port }
}

export function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i < 0 ? p : p.slice(0, i)
      out += seg; p = p.slice(seg.length)
    }
  }
  return out
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const UNRES = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRES.test(c) ? c : '%' + h.toUpperCase()
  })
}
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function checkPct(t) {
  const bad = (s) => s !== undefined && /%(?![0-9A-Fa-f]{2})/.test(s)
  let ui, host
  if (t.authority !== undefined) ({ userinfo: ui, host } = splitAuthority(t.authority))
  for (const [n, v] of [['path', t.path], ['userinfo', ui], ['host', host], ['query', t.query], ['fragment', t.fragment]]) {
    if (bad(v)) return n
  }
  return null
}

export function normalize(t) {
  const scheme = t.scheme === undefined ? undefined : lower(t.scheme)
  let authority
  if (t.authority !== undefined) {
    const { userinfo, host, port } = splitAuthority(t.authority)
    authority = ''
    if (userinfo !== undefined) authority += pct(userinfo) + '@'
    authority += lower(pct(host))
    if (port !== undefined && port !== '' && !(scheme in DEFAULT && DEFAULT[scheme] === port)) authority += ':' + pct(port)
  }
  let path = removeDots(pct(t.path))
  if (authority !== undefined && path === '') path = '/'
  return recompose({
    scheme, authority, path,
    query: t.query === undefined ? undefined : pct(t.query),
    fragment: t.fragment === undefined ? undefined : pct(t.fragment),
  })
}

export function recompose(t) {
  let s = ''
  if (t.scheme !== undefined) s += t.scheme + ':'
  if (t.authority !== undefined) s += '//' + t.authority
  s += t.path
  if (t.query !== undefined) s += '?' + t.query
  if (t.fragment !== undefined) s += '#' + t.fragment
  return s
}

export function resolve(base, r) {
  const t = {}
  if (r.scheme !== undefined) {
    Object.assign(t, r, { path: removeDots(r.path) })
  } else if (r.authority !== undefined) {
    Object.assign(t, r, { scheme: base.scheme, path: removeDots(r.path) })
