export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    const fail = (m) => { throw new ParseError(n, m) }
    const num = (field, s, least) => {
      if (!COUNT.test(s) || BigInt(s) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(s)
    }
    const word = w[0]
    if (word !== 'bucket' && word !== 'window' && word !== 'route' && word !== 'event') fail(`unknown directive ${word}`)
    const late = () => { if (events.length > 0) fail('declarations must come before the first event') }

