    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function arg() {
    const e = cmp()
    return e
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Bad()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw new Bad()
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { n: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw new Bad()
        }
        return { n: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.k !== 'word') throw new Bad()
        p++
        if (isOp('(')) throw new Bad()
        return { n: 'range', a: t.v, b: t2.v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { n: 'bool', v: true }
      if (u === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', w: t.v }
    }
    throw new Bad()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    // misplaced ranges
    const walk = (n, direct) => {
      if (n.n === 'range') { if (!direct) misplaced = true }
      else if (n.n === 'bin') { walk(n.l, false); walk(n.r, false) }
      else if (n.n === 'un') walk(n.e, false)
      else if (n.n === 'call') n.args.forEach((a) => walk(a, true))
    }
    walk(e, false)
    return { ast: e, misplaced }
  } catch (x) {
    if (x instanceof Bad) return null
    throw x
  }
}

function rangeCells(a, b) {
  const A = parseAddr(a), B = parseAddr(b)
  if (!A || !B) return null
  const out = []
  for (let c = Math.min(A.col, B.col); c <= Math.max(A.col, B.col); c++)
    for (let r = Math.min(A.row, B.row); r <= Math.max(A.row, B.row); r++) out.push(colName(c) + r)
  return out
}

// ---- evaluation
for (const c of cells.values()) {
  const s = c.content
  if (s[0] === '=') c.parsed = parseFormula(s.slice(1))
}

const memo = new Map()
const busy = new Set()

function cellValue(key) {
  const c = cells.get(key)
  if (!c) return num(0)
  if (memo.has(key)) return memo.get(key)
  if (busy.has(key)) return err('#CYCLE!')
  busy.add(key)
  let v
  const s = c.content
  if (s[0] === '=') {
    if (!c.parsed || c.parsed.misplaced) v = err('#ERR!')
    else v = ev(c.parsed.ast)
  } else if (s === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = num(parseFloat(s))
  else if (ERRS.has(s)) v = err(s)
  else v = { t: 's', v: s }
  busy.delete(key)
  memo.set(key, v)
  return v
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { n: 0, s: 1, b: 2 }
function cp(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 's') return cp(a.v, b.v)
  if (a.t === 'b') return (a.v ? 1 : 0) - (b.v ? 1 : 0)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function ev(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'b', v: n.v }
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const x = toNum(ev(n.e))
      if (x.t === 'e') return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = ev(n.l)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (l.t === 'e') return l
        const r = ev(n.r)
        if (r.t === 'e') return r
        const d = compare(l, r)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { t: 'b', v: res }
      }
      const a = toNum(l)
      if (a.t === 'e') return a
      const b = toNum(ev(n.r))
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return call(n)
  }
}

function call(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'ABS' || name === 'IF') {
    if (args.length !== (name === 'ABS' ? 1 : 3)) return err('#ERR!')
    if (name === 'ABS') {
      if (args[0].n === 'range') return err('#ERR!')
      const x = toNum(ev(args[0]))
      return x.t === 'e' ? x : num(Math.abs(x.v))
    }
    if (args[0].n === 'range') return err('#ERR!')
    const c = ev(args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    const br = args[truth ? 1 : 2]
    return br.n === 'range' ? err('#ERR!') : ev(br)
  }
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.n === 'range') {
      const cs = rangeCells(a.a, a.b)
      if (!cs) vals.push(err('#REF!'))
      else for (const k of cs) vals.push(cellValue(k))
    } else vals.push(ev(a))
  }
  const e = vals.find((v) => v.t === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const ns = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    ns.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(ns.reduce((a, b) => a + b, 0))
    case 'AVG': return fin(ns.reduce((a, b) => a + b, 0) / ns.length)
    case 'MIN': return num(ns.reduce((a, b) => (b < a ? b : a)))
    default: return num(ns.reduce((a, b) => (b > a ? b : a)))
  }
}

function fmt(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'e': return v.v
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function depsOf(ast, set) {
  const add = (w) => { const a = parseAddr(w); if (a) set.set(a.key, a) }
  const walk = (n) => {
    if (n.n === 'ref') add(n.w)
    else if (n.n === 'range') {
      const cs = rangeCells(n.a, n.b)
      if (cs) for (const k of cs) add(k)
    } else if (n.n === 'bin') { walk(n.l); walk(n.r) }
    else if (n.n === 'un') walk(n.e)
    else if (n.n === 'call') n.args.forEach(walk)
  }
  walk(ast)
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
for (const c of sorted) {
  if (mode[0] === 'values') out += `${c.key}=${fmt(cellValue(c.key))}\n`
  else {
    const set = new Map()
    if (c.parsed) depsOf(c.parsed.ast, set)
    const ds = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${c.key}:${ds.map((d) => ' ' + d.key).join('')}\n`
  }
}
process.stdout.write(out)
