/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scanner.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

const source = readFileSync(0, 'utf8')
let tokens
try {
  tokens = scan(source)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.column}: ${e.reason}\n`)
  process.exit(2)
}

let out = ''
if (mode === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.column} ${t.kind} ${t.body}\n`
} else {
  const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
  for (const t of tokens) counts[t.kind]++
  for (const k of Object.keys(counts)) out += `${k} ${counts[k]}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
