{"file_path":"src/scanner.js","content":"export class ScanError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.')

const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isIdentChar = (c) => isLetter(c) || isDigit(c) || c === '_'

export function scan(source) {
  const cp = Array.from(source)
  const n = cp.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let k = 0; k < n; k++) {
    lines[k] = l
    cols[k] = c
    if (cp[k] === '\n') {
      l++
      c = 1
    } else if (cp[k] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (at, reason) => {
    throw new ScanError(lines[at], cols[at], reason)
  }

  const tokens = []
  const push = (kind, at, body) => tokens.push({ kind, line: lines[at], column: cols[at], body })
  let i = 0

  // Consume a digit run starting at j where the first char need not be checked;
  // returns the end index. `_` is allowed only between two digits.
  const run = (j, isD) => {
    while (j < n) {
      if (isD(cp[j])) j++
      else if (cp[j] === '_' && j > 0 && isD(cp[j - 1]) && isD(cp[j + 1])) j++
      else break
    }
    return j
  }

  while (i < n) {
    const ch = cp[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      i++
      continue
    }
    if (ch === '/' && cp[i + 1] === '/') {
      while (i < n && cp[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cp[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cp[i] === '/' && cp[i + 1] === '*') {
          depth++
          i += 2
        } else if (cp[i] === '*' && cp[i + 1] === '/') {
          depth--
          i += 2
        } else i++
      }
      if (depth > 0) fail(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && cp[i + 1] === '"') {
      let j = i + 2
      while (j < n && cp[j] !== '"') j++
      if (j >= n) fail(i, 'unterminated string')
      push('rawstring', i, JSON.stringify(cp.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isLetter(ch) || ch === '_') {
      let j = i + 1
      while (j < n && isIdentChar(cp[j])) j++
      const text = cp.slice(i, j).join('')
      push(KEYWORDS.has(text) ? 'keyword' : 'ident', i, text)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      let bad = false
      const p = cp[i + 1]
      let pred = null
      if (ch === '0' && (p === 'x' || p === 'X')) pred = isHex
      else if (ch === '0' && (p === 'b' || p === 'B')) pred = isBin
      else if (ch === '0' && (p === 'o' || p === 'O')) pred = isOct
      if (pred) {
        j = i + 2
        if (!pred(cp[j])) bad = true
        else j = run(j, pred)
      } else {
        j = run(i, isDigit)
        if (cp[j] === '.' && isDigit(cp[j + 1])) j = run(j + 1, isDigit)
        if (cp[j] === 'e' || cp[j] === 'E') {
          if (isDigit(cp[j + 1])) j = run(j + 1, isDigit)
          else if ((cp[j + 1] === '+' || cp[j + 1] === '-') && isDigit(cp[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (bad || isIdentChar(cp[j])) {
        while (j < n && isIdentChar(cp[j])) j++
        fail(i, `invalid number ${cp.slice(i, j).join('')}`)
      }
      push('number', i, cp.slice(i, j).join(''))
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let value = ''
      for (;;) {
        if (j >= n) fail(i, 'unterminated string')
        const d = cp[j]
        if (d === '"') {
          j++
          break
        }
        if (d === '\n') fail(j, 'newline in string')
        if (d !== '\\') {
          value += d
          j++
          continue
        }
        const e = cp[j + 1]
        if (e === undefined) fail(i, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          value += simple[e]
          j += 2
        } else if (e === 'x') {
          if (isHex(cp[j + 2]) && isHex(cp[j + 3])) {
            value += String.fromCodePoint(parseInt(cp[j + 2] + cp[j + 3], 16))
            j += 4
          } else fail(j, 'invalid escape \\x')
        } else if (e === 'u') {
          if (cp[j + 2] !== '{') fail(j, 'invalid escape \\u')
          let k = j + 3
          let hex = ''
          while (k < n && isHex(cp[k])) hex += cp[k++]
          if (k >= n) fail(i, 'unterminated string')
          if (hex === '' || cp[k] !== '}' || parseInt(hex, 16) > 0x10ffff) fail(j, 'invalid escape \\u')
          value += String.fromCodePoint(parseInt(hex, 16))
          j = k + 1
        } else fail(j, `invalid escape \\${e}`)
      }
      push('string', i, JSON.stringify(value))
      i = j
      continue
    }
    const two = ch + (cp[i + 1] ?? '')
    if (PUNCT2.has(two)) {
      push('punct', i, two)
      i += 2
      continue
    }
    if (PUNCT1.has(ch)) {
      push('punct', i, ch)
      i++
      continue
    }
    fail(i, `unexpected character ${ch}`)
  }
  return tokens
}
"}

