import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(i, reason) { super(reason); this.i = i; this.reason = reason }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const cp = Array.from(text)
  const n = cp.length
  const line = new Array(n + 1)
  const col = new Array(n + 1)
  let l = 1, c = 1
  for (let k = 0; k < n; k++) {
    line[k] = l; col[k] = c
    if (cp[k] === '\n') { l++; c = 1 }
    else if (cp[k] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  const tokens = []
  const push = (i, kind, body) => tokens.push({ pos: `${line[i]}:${col[i]}`, kind, body })
  let i = 0

  // digit run with single underscores between digits; returns new index
  const run = (j, ok) => {
    while (j < n) {
      if (ok(cp[j])) j++
      else if (cp[j] === '_' && j > 0 && ok(cp[j - 1]) && ok(cp[j + 1])) j++
      else break
    }
    return j
  }
  const fail = (start, j, ) => {
    while (j < n && isIdChar(cp[j])) j++
    throw new ScanError(start, 'invalid number ' + cp.slice(start, j).join(''))
  }

  while (i < n) {
    const ch = cp[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cp[i + 1] === '/') {
      while (i < n && cp[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cp[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cp[i] === '/' && cp[i + 1] === '*') { depth++; i += 2 }
        else if (cp[i] === '*' && cp[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) throw new ScanError(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && cp[i + 1] === '"') {
      let j = i + 2
      while (j < n && cp[j] !== '"') j++
      if (j >= n) throw new ScanError(i, 'unterminated string')
      push(i, 'rawstring', JSON.stringify(cp.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (j < n && isIdChar(cp[j])) j++
      const w = cp.slice(i, j).join('')
      push(i, KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      const p = (cp[i + 1] || '')
      let ok = null
      if (ch === '0') {
        if (p === 'x' || p === 'X') ok = isHex
        else if (p === 'b' || p === 'B') ok = isBin
        else if (p === 'o' || p === 'O') ok = isOct
      }
      if (ok) {
        j = i + 2
        if (!ok(cp[j])) fail(i, j)
        j = run(j, ok)
      } else {
        j = run(i, isDigit)
        if (cp[j] === '.' && isDigit(cp[j + 1])) j = run(j + 1, isDigit)
        if (cp[j] === 'e' || cp[j] === 'E') {
          let k = j + 1
          if (cp[k] === '+' || cp[k] === '-') k++
          if (isDigit(cp[k])) j = run(k, isDigit)
        }
      }
      if (isIdChar(cp[j])) fail(i, j)
      push(i, 'number', cp.slice(i, j).join(''))
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let out = ''
      for (;;) {
        if (j >= n) throw new ScanError(i, 'unterminated string')
        const d = cp[j]
        if (d === '"') { j++; break }
        if (d === '\n') throw new ScanError(j, 'newline in string')
        if (d !== '\\') { out += d; j++; continue }
        const e = cp[j + 1]
        if (e === undefined) throw new ScanError(i, 'unterminated string')
        const bad = () => new ScanError(j, 'invalid escape \\' + e)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.prototype.hasOwnProperty.call(simple, e)) { out += simple[e]; j += 2 }
        else if (e === 'x') {
          if (!isHex(cp[j + 2]) || !isHex(cp[j + 3])) throw bad()
          out += String.fromCharCode(parseInt(cp[j + 2] + cp[j + 3], 16))
          j += 4
        } else if (e === 'u') {
          if (cp[j + 2] !== '{') throw bad()
          let k = j + 3
          let h = ''
          while (isHex(cp[k])) h += cp[k++]
          if (!h || cp[k] !== '}') throw bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) throw bad()
          out += String.fromCodePoint(v)
          j = k + 1
        } else throw bad()
      }
      push(i, 'string', JSON.stringify(out))
      i = j
      continue
    }
    const two = ch + (cp[i + 1] || '')
    if (PUNCT2.includes(two)) { push(i, 'punct', two); i += 2; continue }
    if (PUNCT1.includes(ch)) { push(i, 'punct', ch); i++; continue }
    throw new ScanError(i, 'unexpected character ' + ch)
  }
  return { tokens, line, col }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const text = readFileSync(0, 'utf8')
  let res
  try {
    res = scan(text)
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    const cp = Array.from(text)
    let l = 1, c = 1
    for (let k = 0; k < e.i; k++) {
      if (cp[k] === '\n') { l++; c = 1 }
      else if (cp[k] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
      else c++
    }
    process.stderr.write(`error: ${l}:${c}: ${e.reason}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of res.tokens) out += `${t.pos} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${res.tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${res.tokens.length}\n`
  }
  process.stdout.write(out)
}

