  workers = Number(args[1])
} else fail(USAGE)

let input
try { input = readFileSync(0, 'utf8') } catch { input = '' }
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
const costs = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (costs.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    costs.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) depUses.push(x)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of depUses) if (!costs.has(x)) fail(`error: unknown task ${x}`)

const names = [...costs.keys()].sort(cmp)
const dl = new Map(names.map((k) => [k, [...(deps.get(k) ?? [])].sort(cmp)]))

// cycle detection
const color = new Map()
const stack = []
function dfs(u) {
  color.set(u, 1)
  stack.push(u)
  for (const v of dl.get(u)) {
    const c = color.get(v)
    if (c === 1) {
      const cyc = stack.slice(stack.indexOf(v)).concat(v)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!c) dfs(v)
  }
  stack.pop()
  color.set(u, 2)
}
for (const k of names) if (!color.get(k)) dfs(k)

// start/finish/depth
const start = new Map(), finish = new Map(), depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0n, d = 0
  for (const v of dl.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s); finish.set(u, s + costs.get(u)); depth.set(u, d)
}
for (const k of names) calc(k)
let total = 0n
for (const k of names) if (finish.get(k) > total) total = finish.get(k)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ??= []).push(k)
  ws.forEach((w, i) => { out += `wave ${i}: ${w.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const v of dl.get(k)) rev.get(v).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const p of rev.get(u)) { const x = pr(p); if (x > m) m = x }
    prio.set(u, m + costs.get(u))
    return m + costs.get(u)
  }
  for (const k of names) pr(k)
  const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : cmp(a, b)))
  const done = new Map()
  const free = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n, left = names.length, makespan = 0n
  while (left > 0) {
    for (;;) {
      const wi = free.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((k) => !done.has(k) && dl.get(k).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      const f = t + costs.get(task)
      done.set(task, f)
      free[wi] = f
      runs[wi].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
      left--
    }
    if (left === 0) break
    let next = null
    for (const f of free) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  runs.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
