  const w = order.find((x) => counts.get(x) * 2n > active)
  if (w !== undefined) {
    winner = w
    break
  }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let set = [...cont].filter((x) => counts.get(x) === min)
  for (;;) {
    if (set.length === 1) break
    let r = 0
    let split = false
    for (; r < roundNo; r++) {
      const vs = set.map((x) => history.get(x)[r])
      const m = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.some((v) => v !== m)) {
        set = set.filter((x) => history.get(x)[r] === m)
        split = true
        break
      }
    }
    if (!split) break
  }
  const loser = set.reduce((a, b) => (b > a ? b : a))
  cont.delete(loser)
  out.push(`eliminated ${loser}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'tally') process.stdout.write(`rounds ${roundNo}\n${end}\n`)
else process.stdout.write(out.join('\n') + '\n' + end + '\n')
