  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (names !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const nm of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(nm)) fail(`error: line ${n}: invalid candidate name ${nm}`)
      if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is declared twice`)
      seen.add(nm)
    }
    names = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!names.includes(nm)) fail(`error: line ${n}: unknown candidate ${nm}`)
      if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
}
if (names === null) fail('error: no candidates')

const cont = new Set(names)
const history = new Map(names.map((x) => [x, []]))
const out = []
let winner = null
let roundNo = 0
for (;;) {
  roundNo++
  const counts = new Map([...cont].map((x) => [x, 0n]))
  let active = 0n
  let total = 0n
  for (const b of ballots) {
    total += b.count
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [k, v] of counts) history.get(k).push(v)
  const order = [...cont].sort((a, b) => (counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  out.push(`round ${roundNo}: ` + order.map((x) => `${x}=${counts.get(x)}`).join(' ') + ` exhausted=${total - active}`)
  if (active === 0n) break
  const w = order.find((x) => counts.get(x) * 2n > active)
  if (w !== undefined) {
    winner = w
    break
  }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let set = [...cont].filter((x) => counts.get(x) === min)
  for (;;) {
    if (set.length === 1) break
    let r = 0
    let split = false
    for (; r < roundNo; r++) {
      const vs = set.map((x) => history.get(x)[r])
      const m = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.some((v) => v !== m)) {
        set = set.filter((x) => history.get(x)[r] === m)
        split = true
        break
      }
    }
    if (!split) break
  }
  const loser = set.reduce((a, b) => (b > a ? b : a))
  cont.delete(loser)
  out.push(`eliminated ${loser}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'tally') process.stdout.write(`rounds ${roundNo}\n${end}\n`)
else process.stdout.write(out.join('\n') + '\n' + end + '\n')
EOF
